import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"隨","description":"高岛易断 - 隨","frontmatter":{"title":"隨","description":"高岛易断 - 隨"},"headers":[],"relativePath":"zh/classics/takashima/017.md","filePath":"zh/classics/takashima/017.md"}'),i={name:"zh/classics/takashima/017.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="隨" tabindex="-1">隨 <a class="header-anchor" href="#隨" aria-label="Permalink to “隨”">​</a></h1><h2 id="隨-1" tabindex="-1">隨 <a class="header-anchor" href="#隨-1" aria-label="Permalink to “隨”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>随：元亨利贞，无咎。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>卦体《震》自下而震动，《兑》在上而感悦，从而应和之为《随》。盖有舍己从人，乐取于人以为善，故《随》之道，可以致大亨也。《震》为健，得夫《乾》，故曰“元亨”；《巽》于地为刚卤，合夫《坤》，故曰“利贞”。《杂卦》曰“随无故也”，谓上下各从其所处而安，不待有所为也。无故则无事，无事则何咎之有？然失之贞正，则枉己徇人，易于有咎，亦足戒也。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>泽中有雷，随。君子以向晦入宴息。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>此卦以《震》阳陷《兑》阴，有藏伏之象，《象》曰“泽中有雷，随”，不曰雷之动，而曰雷之有，《本义》以雷藏泽中释之，深得其旨，盖知象之取义，在雷伏势时也。君子观此象；故不言动作，但言“宴息”。雷之伏藏，在寒冬，人之宴息，在“向晦”，盖亦各随其时也。君子应天而时行，时当“向晦”，入居于内，宴息以养其身，起居随时，惟宜自适。盖其动也，与雷俱出；其静也，与雷俱入。《豫》之“作乐崇德”，《大壮》之“非礼弗履”，《无妄》之“茂对时育”，皆法春雷之动也；《复》之闭关息旅，《随》之向晦宴息，皆法秋雷之藏也。夫舍百为之烦扰，就一枕之安闲，所以养精神于鼓舞之余，以为将来应用之地。故以形息者，凡民所同；以心息者，君子所独。君子虽才德兼备，当随时适宜，否则亦必有咎，是以遇随之时，韬智藏德，辞禄不居，养晦以遵时，抱道而伏处。文王之服事殷纣，勾践之隐会稽，皆得向晦宴息之义者也，谓之“君子以向晦入宴息”。互卦三、四、五为《巽》，二、三、四为《艮》，《巽》为入，《艮》为止，即入而止息之象也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：目下气运平常，宜暂时晦藏，明年利于远行，至第五年，则可得利。</p><p>○　问战征：宜退守，明年当小有功，必俟六年，斯敌皆就缚矣。</p><p>○　问商业：有货一时难售，来春可以获利。</p><p>○　问家宅：防有伏怪，夜间致多惊惧。</p><p>○　问讼事：恐有牢狱之灾，明年又防征役远行。凶。</p><p>○　问失物：宜在枕席间觅之。</p><p>○　问六甲：生女。</p><p>○　问行人：即归。</p><p>○　问出行：以明年为利。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>此卦六爻，各以随人立义，专取相比相从，不取应爻。“官”，谓心之官，凡人作事，皆以心官主之。“渝”者变也，“有渝”者，谓变易其所主司也。官虽贵有守，处随之时，不可不知权变，变者趋时从权之谓也。此爻刚而得正，为成卦之主，主者不可随人，故不言随。“有渝”而得其正，故曰“贞吉”。“出门”则所见者广，所闻者多，不溺于私，惟善是从，则随不失时，变不失正，虚己听人，广交而有功也，故曰“出门交有功”。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：目下正当换运之时，交入新运，一动便佳，尤利出门。</p><p>○　问商业：货物当贩运出外，得利。</p><p>○　问家宅：当以修造吉，或迁居出外，更利。</p><p>○　问战征：击东者变而击西，击南者变而攻北，吉。</p><p>○　问疾病：恐药不对症，宜改变药饵，乃吉。或于远方求医，更利。</p><p>○　问失物：门外寻之，得。</p><p>○　问六甲：生男。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>占友人某就官，筮得《随》之《萃》。</p><p>断曰：此卦《兑》上《震》下，为刚阳伏而从阴，是《随》卦之所取义也。今占得初爻，足下虽学力刚强，不得不俯从愚柔，亦时为之也。凡始入仕途者，以不熟事务，每事须从老成之指挥，是又随之道也。此中固不能自主，所当舍己而从人，谓之“官有渝，贞吉”。又不宜独处，所当广交以集益，谓之“出门交有功”。后果如此占。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>刚有以自立，谓之随，柔不足自立，谓之系，故初、四、五，刚不言系，二、三、上，皆柔曰系。随则公，故无失；系则私，故有失。六二以柔居阴，与四隔位，遂系乎四，四阳而居阴，谓之“小子”，是隔位为系之谓也。系四则不能比初，初爻为《随》之主，是谓“丈夫”，故曰“系小子，失丈夫”。旧说谓二系初，失在初，阳犹微，谓之小子，五居尊位，谓之丈夫。然初为卦主，何得曰小子？五为君位，何可曰丈夫？且阳爻为丈夫，初阳爻也，目为小子，其说亦反。夫人之所随，得正则远邪，从非则失是，六二系失所系，虽无凶咎之辞，其不吉可不言而知。《象传》曰“弗兼与也”，谓天地之道，无两全之义，“系小子”，必“失丈夫”，理之当然也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：目下气运颠倒，宜自审慎。</p><p>○　问商业：有贪小失大之惧。</p><p>○　问家宅：阴阳倒置，有女子小人弄权，反致家主受制之象。</p><p>○　问战征：只能捉捕敌兵，未获斩将拔旗之捷。</p><p>○　问六甲：生女。</p><p>○　问失物：小品可得，大件必失。</p><p>○　问婚嫁：恐非良缘。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>熊本县人尾藤判事，曾学《易》于余，同氏有女年十八，容貌艳丽，时某缙绅丧妻，以媒求婚于氏，氏因请占其吉凶。筮得《随》之《兑》。</p><p>断曰：此卦刚从柔之象，而非柔从刚之时也。今足下卜嫁女，则女家为柔，而男家为刚也。爻象以刚从柔，殊嫌相反。二爻曰“系小子，失丈夫”，想某缙绅必是老夫也，令女或不喜之，宜嫁少年小子，斯两相得也。氏闻之，如有所感悟曰：夫妇者，女子终生之事也，不可以亲之所好，枉女子之志。遂谢缙绅。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>“丈夫”，指初九；“小子”，指九四。初为《随》卦之主，以刚居阳，出门有功，谓之“丈夫”；四以刚居阴，其义有凶，谓之“小子”，系初失四，故曰“系丈夫，失小子”，正与二爻相反。初爻本欲出门求交，得三之《随》，必与之亲善，故三之《随》初，有求而得也。初以随求人，苟枉己徇人，虽得亦失，故云“利居贞”。六三才虽弱，位得其正，系“贞吉”之初，失“贞凶”之四，是得居贞之利，即随道之善也，所以求道而得道，求仁而得仁，无求而亦自得焉。互卦《巽》为近利，故“有得”。“居贞”者，谓守常止分，以道自固，以义自裁，不以动而妄求也。《象传》曰“志舍下也”，阳上阴下，三居阳位，所系在阳，所失在阴，故曰“志合下也”。一说丈夫指四，小子指初，与二爻以五谓丈夫，前后不同。且四“贞凶”，何得云丈夫？初“有功”何得云小子？于以刚从柔为随，以柔从人为系之说，亦不合。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：目下交正运，求财求名，无不如意。</p><p>○　问商业：小往大来，必得利益。</p><p>○　问战征：主生擒敌将，必得大捷。</p><p>○　问家宅：家道丰富，但防小儿辈有灾。</p><p>○　问疾病：大人无妨，小人恐有不利。</p><p>○　问六甲：恐生而不育。</p><p>○　问失物：得。</p><p>○　问婚嫁：主结高亲。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>神奈川町净土宗成佛寺住职辨真和尚，名僧辨玉和尚之徒，修小乘之学者也，一日来问余讲《易》，感悟而欲学《易》，且云学之得成与否，请烦一筮。筮而得《随》之《革》。</p><p>断曰：《随》卦虽为刚从柔，在爻则否，阳爻曰随，阴爻曰系。今子就余学《易》，即探以内典之精奥，旁求神《易》之微妙，是所求皆天神之道，不关尘世琐细小务，故谓“系丈夫，失小子”也。故从余学易，纵使内典中有难解之事，自可求神而问之，求之必得，现世未来，皆得安心决定也。故曰“随有求得，利居贞”也。和尚闻之，大悦，从此学《易》，今尚不倦。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>获者，取非其有之辞，“有获”者，谓得天下之心，使之随己也。是私据其所有，而不归于五，失臣道也，故曰“贞凶”。为臣之道无他，惟在以诚相孚而已，“诚则明”，明则无疑，无疑则君臣一心，德施于民而民随之。其得民之随者，相率而共随于君，足以成君之功，致国之治者，皆在此相孚有道耳，复何有咎？否则上下疑猜，即所当获，不免启挟功凌上之嫌，虽正亦凶也。九四具阳刚之才，处大臣之位，才高致谤，位重启嫌，一涉偏私，便招凶祸。惟其中之所存，一秉于诚，外之所行，一循夫理，尽其道以事上，明其几以保身，位虽高不疑于迫，势虽重不嫌于专，君嘉其让，民服其谦，得随之时，协随之宜，何咎之有？故曰“有孚在道，以明，何咎”。“有孚”者，谓有孚于九五也；“明”者，谓自明其志也。自古人臣处功名之际，不克保终者，多由我心之不孚，与不能自明其志也。如汉萧何韩信，皆受君重任，韩信求封于齐，求王于楚，无欲而不获者也，久之积疑生嫌，卒不免祸。萧何虽素知高帝之心，得保首领而终，不免械击之辱，是于“有孚”“以明”之义，犹未尽者也。如唐郭子仪权倾天下，而上不忌，功盖一世，而上不疑，可谓得“有孚在道”者矣。《象传》曰“有孚在道，明功也”，以功云者，释爻之“何咎”。盖“有孚”者，即以孚随之道；“明功”者，即明其随之功也。一说“随有获”者，谓以权在我，任己所为之意；“贞”者谓所系国家之正务；“凶”者有僭逼之疑；“有孚”者心尽其诚；“在道”者行尽其道；“何咎”者，无失臣职之意也。亦通。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：目下有凶有吉，利在单月，不利双月，明年则吉。</p><p>○　问商业：获利后，防有意外之祸，必俟辨明方可。</p><p>○　问家宅：或新买，或新造，皆不吉。</p><p>○　问战征：小胜后，防大败。</p><p>○　问疾病：先凶后吉。</p><p>○　问讼事：始审凶，上控则无咎。</p><p>○　问失物：一时难觅，待后方见。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>明治二十七年六月，相识岩谷松平氏来告曰：往年政府，下付士族以金禄公债证书，鹿儿岛县士族中，有遗漏此典者，今欲补请恩给，请占其准否。筮得《随》之《屯》。</p><p>断曰：随有获者，是专意求获之谓也。鹿儿岛县士族，维新之际，伟烈丰功，为政府所优待，遍世所知也。今欲谋请恩给，占得《随》之四爻，以阳居阴，乘政府之优待，意在强求，务期必获，故《象传》曰“随有获，其义凶也”。然当以公平之道，请求于上，必可得许，谓之“有孚在道，明功也”。</p><p>某缙绅来，请占某贵显气运，筮得《随》之《屯》。</p><p>断曰：此卦吾能从人，则人亦从我。今占得四爻，某贵显在现职，众人咸乐为随从。其所以随从者，非服从其德量，实欲攀附其权势也。若因此自负得民，则不祥之道也，故曰“贞凶”。际此民心之归向，以诚相孚，以明自审，即所获以归诸君上，不以自私，道可孚也，功可明也，何咎之有？反是则难免于咎。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>“嘉”者，善也，谓择善而从之。随其善者，非随其人也。“孚”者，以真实诚一之心，相与感通也。“吉”者，谓君明臣良，天下从之，无不服从其化也。舍己从人，乐取于人以为善，即所谓“孚于嘉”是也。五爻阳刚中正，位居至尊，为全卦悦随之主，是圣君至诚相感，以乐从天下之善者也。夫人主之尊，其所随之可否，悉系国家之休戚。尚贤而信之，其所以吉也，如此则不失人，亦不失己，随道之正也，谓之“孚于嘉，吉”。《象传》曰“位中正也”，以阳刚居阳位，得其正也，处中正之位，行中正之道，是以嘉也。一说此爻以阳刚，比上六之柔正，谓上六以柔居阴，有女子之象。今九五孚之为婚，是取婚礼为嘉礼之义。盖随之道，莫切乎夫妇，天下之政化，始于闺门，故曰“孚于嘉”。亦通。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：目下处盛运，万事获吉。</p><p>○　问商业：以其货物嘉美，获利百倍。</p><p>○　问家宅：必是积善之家，众咸信从，为一乡之望也。</p><p>○　问战征：军众同心，必获胜捷，吉。</p><p>○　问婚嫁：百年好合，大吉。</p><p>○　问讼事：和好。</p><p>○　问疾病：吉。</p><p>○　问六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治三年某月，应某贵显之召，贵显曰有一事，为烦一筮。筮得《随》之《震》。</p><p>断曰：此卦当秋冬之时，《震》雷藏于《兑》泽，有强随弱之象，《彖传》谓之“刚来而下，柔动而悦，大亨贞，无咎”。全卦初、二、五、六四爻，以刚随柔，皆谓得位，四、三二爻，以柔系刚，谓之失位，惟四爻系恋于柔，且能率众而《随》九五。由是观之，知有威权者，能使众从己，相率而从九五之君也。今占得九五，可见天下之人心，无不从君上之所命也。天命如此，故《彖传》曰：“随时之义大矣哉！”后未几而有废藩置县之令。</p><p>元老院议官某氏，转任某县知事，将赴任，请余占施政准则。筮得《随》之《震》。</p><p>断曰：《随》卦有以刚从柔之义，是降尊从卑之象。今足下治该县，下从民情，不涉私意，人民自然嘉乐悦豫，可以随从归服也，谓之“孚于嘉，吉”。从前该县之治，纷争不绝，某氏赴任之后，因此施治，静稳平和，乃得无事。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“拘”者，执而不弃之谓也；“维”者，交结也。管子曰：“礼义廉耻，谓国之四维，乃维民之道也。”盖其所随，极其诚意缠绵，固结而有不可解者矣。至诚之极，可以孚君心，可以享鬼神，是随之极则也。“王”者，指周王而言；“西山”指歧山而言。此爻以阴居《随》之极位，天下之臣民，随顺化服之极也，故不复言随，反将拘系九五，九五亦从其所系而维之。居《随》之极，效至诚于君，相知之深，相信之笃，终始无间者也。譬如一物，人所爱好，惟恐或失之，既“拘系之”，又从而维之，即所谓拳拳服膺，而不失之意也。昔周大王避戎狄之难，去豳移居歧山之下，民之从之者如归市，是“拘系之”也，大王亦即以道维之。夫大王之去豳也，势穷而人益随之，故周室之业，自此而兴。文王之时，天下之人，无思不服，而文王尚守臣节，享大王于封内之西山，不敢僭郊之禘礼。固结其鬼神，正所以固结于君也，故有此上六之诚意，足以通神明，神明亦随之，谓之“王用享于西山”。凡《易》之爻曰“王用享”者三，皆谓王者用，此爻则以贤臣而享山川，非指其爻而为王也。若夫使之主祭，而百神享之，可以见王者之克当天心，莫大于用贤也。《象传》“上穷也”者，“上”，即尚字，是谓随道之极，无以复尚之也。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：目下左支有绌，不甚如意。</p><p>○　问商业：坚固结实，稳当可做，但未能事事舒展。</p><p>○　问家宅：恐防范约束过严，家人怨苦。</p><p>○　问疾病：祷之则吉。</p><p>○　问婚嫁：有赤绳系臂之缘。</p><p>○　问讼事：恐有桎梏困系之患。</p><p>○　问失物：是自己包裹藏之，未尝失也。</p><p>○　问六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>南部山本宽次郎氏，余之旧友也。维新之际，赴函馆之役，边地战争之时，在将帅中颇有勇武之名。明治十二年七月，与旧藩士五人，过访敝庐，谓余曰：君有谈《易》之癖，以为快乐，予甚苦之，若换以他乐如何？君自言《易》占必中，谓政府所不可不用；陆海军关人命之重，系国家之存亡；裁判所，明是非，分曲直，皆不可不用。然于未来之事，或中或不中，恐难一一预知。余曰：小人闻道而笑之，“不笑不足以为道”，《易》岂如足下所言哉？余二十年之久，未尝一日废《易》，所以然者，以百占百中也。山本氏闻之，笑曰：果如君言，则吾命何时而终？愿一占迟速，俾可前知。余曰：是极容易。筮得《随》之《无妄》。</p><p>断曰：《随》者为《震》之长男，从《兑》之少女，又为归魂之卦。今占得上爻，君之命，可终于本年也。君之妻子墓祭之象，正见于爻辞：“拘系之”者，谓系连于君者；“维之”者，谓有子女；“亨于西山”者，谓葬足下于宅之西也。山本氏听毕，冷笑，如不介意，诸士或疑或笑。既而其年十月，南部某寄书于余云：山本氏昨夜急罹中风，半身不遂，因召唤妻子于本国。其妻子未至之时，请借神奈川别邸中一户为寓。未几妻子来迎，同归盛罔，迨十二月不起。于是当时诸士，听余言而笑者，皆为惊叹。</p><p>明治三十一年十月，宪政党分离为二，旧改进党称宪政本党，旧自由党称宪政党，各树旗帜。时策士井上角五郎、尾崎三郎、雨宫敬治郎等，见宪政党权力之薄，使之提携山悬内阁，乘其虚，将使实行板垣伯所主张铁道国有论。三氏来请占宪政党内”阁之提携成否，筮得《随》之《无妄》。</p><p>断曰：此卦下卦之雷动，上卦之泽悦《系辞传》曰：“服牛乘马，引重致远，以利天下，盖取诸随。”由是观之，宪政党不啻随从政府，粉身碎骨，能贯彻政府之意向。今占得上爻，其辞曰“拘系之，乃从维之”，谓提携之密着也；“王用亨于西山”，谓政府得宪政党之援助，海陆军扩张之费用，得如其意，喜悦之余，得举行靖国神社之祭礼也。后果如此占。</p>',107)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
